/**
 * Get local date in YYYY-MM-DD format
 * Avoids timezone issues with toISOString() which returns UTC
 * @param {Date|string|number} dateInput - Date object, ISO string, or timestamp (defaults to now)
 * @returns {string} Local date string like "2025-01-27"
 */
function getLocalDateString(dateInput = new Date()) {
    // Convert input to Date object if needed
    const date = dateInput instanceof Date ? dateInput : new Date(dateInput);
    
    // Handle invalid dates
    if (isNaN(date.getTime())) {
        console.warn('Invalid date passed to getLocalDateString:', dateInput);
        return new Date().toISOString().split('T')[0]; // Fallback
    }
    
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
}

/**
 * Get yesterday's date in local YYYY-MM-DD format
 * @returns {string} Yesterday's local date string
 */
function getYesterdayLocalDateString() {
    const yesterday = new Date();
    yesterday.setDate(yesterday.getDate() - 1);
    return getLocalDateString(yesterday);
}

/**
 * Fetch weather data for a player if they have weather enabled
 * @param {string} playerId - Player's user ID
 * @param {object} weatherService - Weather service instance
 * @returns {Promise<object|null>} Weather data or null
 */
async function fetchWeatherForPlayer(playerId, weatherService) {
    if (!weatherService || !playerId) return null;

    try {
        const playerUser = await storageManager.getUser(playerId);
        if (playerUser?.weatherEnabled && playerUser?.location?.zipCode) {
            const weatherData = await weatherService.getWeatherByZipCode(
                playerUser.location.zipCode,
                playerUser.location.country || 'us'
            );
            return weatherData;
        }
    } catch (error) {
        // Silently fail - weather is optional
    }

    return null;
}

