            // Load season info and progress
            this.state.currentSeason = teamsLeaguesManager.getCurrentSeason();
            this.state.seasonProgress = await teamsLeaguesManager.getSeasonProgress(user.id);

            // Load user's team
            this.state.userTeam = await teamsLeaguesManager.getUserTeam(user.id);

            // Load ELO leaderboard
            this.state.eloLeaderboard = await teamsLeaguesManager.getEloLeaderboard(50);
