    /**
     * Track user's best leaderboard rank for achievements
     * Updates bestPointsRank, bestEloRank, or bestSeasonRank when user achieves a new best
     */
    async updateBestLeaderboardRank(type = 'points') {
        try {
            const user = userManager.getCurrentUser();
            if (!user) return;
            
            // Get the appropriate leaderboard based on type
            let leaderboard;
            if (type === 'elo') {
                leaderboard = this.state.eloLeaderboard || [];
            } else if (type === 'season') {
                leaderboard = this.state.seasonXpLeaderboard || [];
            } else {
                leaderboard = this.state.leaderboard || [];
            }
            
            const userIndex = leaderboard.findIndex(p => p.id === user.id);
            
            if (userIndex === -1) return; // User not on leaderboard
            
            const currentRank = userIndex + 1;
            const fieldName = type === 'points' ? 'bestPointsRank' : 
                              type === 'elo' ? 'bestEloRank' : 'bestSeasonRank';
            
            const currentBest = user[fieldName] || 999999;
            
            if (currentRank < currentBest) {
                await storageManager.updateUser(user.id, { [fieldName]: currentRank });
                user[fieldName] = currentRank;
                console.log(`🏆 New best ${type} rank: #${currentRank}`);
                
                // Check for leaderboard achievements
                const { achievementManager } = await import('./modules/achievements.js');
                if (achievementManager) {
                    await achievementManager.checkLeaderboardAchievements(currentRank);
                }
            }
        } catch (error) {
            console.error('Error updating best leaderboard rank:', error);
        }
    }

