    /**
     * Handle real-time pending sessions update
     */
    handlePendingSessionsUpdate(sessions) {
        const currentPending = (userManager.sessions || []).filter(s => s.pending);
        const newItems = sessions.filter(s => !currentPending.find(c => c.id === s.id));

        if (newItems.length > 0) {
            newItems.forEach(item => {
                this.showToast({
                    type: 'info',
                    title: '📬 New Activity',
                    message: `${item.loggedByName || 'Someone'} logged a session for you!`,
                    duration: 5000
                });
            });
        }

        userManager.sessions = [
            ...(userManager.sessions || []).filter(s => !s.pending),
            ...sessions
        ];

        // Don't re-render if profile modal is open to prevent freeze
        // Don't re-render if wizard is open - would destroy wizard event listeners
        if (this.state.currentView === 'practice' && !this.state.showProfileModal && !this.state.showBulkLogWizard && !this.state.showBulkLogModal) {
            this.render();
        }
    }

