    /**
     * Delete a routine
     * @param {string} routineId - ID of routine to delete
     */
    async deleteRoutine(routineId) {
        try {
            const routine = this.state.recentRoutines.find(r => r.id === routineId);
            if (!routine) {
                throw new Error('Routine not found');
            }

            const scoreText = routine.totalStats
                ? `${routine.totalStats.totalMakes}/${routine.totalStats.totalAttempts} (${routine.totalStats.overallPercentage?.toFixed(1) || '0.0'}%)`
                : 'N/A';

            const confirmed = confirm(
                `Are you sure you want to delete this routine?\n\n` +
                `Routine: ${routine.routineName}\n` +
                `Duration: ${routine.duration || 0} minutes\n` +
                `Score: ${scoreText}\n` +
                `Points: ${routine.points || 0}`
            );

            if (!confirmed) {
                return;
            }

            const user = userManager.getCurrentUser();
            const activityDate = routine.timestamp || routine.endTime || routine.date;

            // Remove routine from any active friend challenges
            await this.removeSessionFromChallenges(routineId);

            // Only remove points if routine wasn't pending
            if (!routine.pending) {
                user.totalPoints = Math.max(0, user.totalPoints - (routine.points || 0));
                user.totalRoutines = Math.max(0, (user.totalRoutines || 0) - 1);
                // Remove makes/putts from routine
                const routineMakes = routine.totalStats?.totalMakes || routine.drillScores?.reduce((sum, d) => sum + (d.makes || 0), 0) || 0;
                const routineAttempts = routine.totalStats?.totalAttempts || routine.drillScores?.reduce((sum, d) => sum + (d.attempts || 0), 0) || 0;
                user.totalMakes = Math.max(0, (user.totalMakes || 0) - routineMakes);
                user.totalPutts = Math.max(0, (user.totalPutts || 0) - routineAttempts);
                await storageManager.saveUser(user);
                
                // Remove Season XP
                await teamsLeaguesManager.removeSeasonXp(user.id, 'completeRoutine', activityDate);
            }

            // Delete routine
            await storageManager.deleteRoutineCompletion(user.id, routineId);

            // Reload current user to get updated totalPoints
            await userManager.reloadCurrentUser();

            // Reload data
            await this.loadRecentPractice();
            await this.loadLeaderboard();

            // Revalidate achievements if routine wasn't pending
            if (!routine.pending) {
                const revokedAchievements = await achievementManager.revalidateAchievements(
                    this.state.recentRoutines || [],
                    this.state.recentGames || []
                );
                
                // Remove XP for each revoked achievement
                for (const achievementId of revokedAchievements) {
                    await teamsLeaguesManager.removeSeasonXp(user.id, 'earnAchievement', activityDate);
                }
                
                if (revokedAchievements.length > 0) {
                    this.showCustomAlert(`Routine deleted. ${revokedAchievements.length} achievement(s) revoked.`, 'warning');
                } else {
                    this.showCustomAlert('Routine deleted successfully', 'success');
                }
            } else {
                this.showCustomAlert('Routine deleted successfully', 'success');
            }

            this.render();

        } catch (error) {
            console.error('Error deleting routine:', error);
            this.showCustomAlert('Failed to delete routine: ' + error.message, 'error');
        }
    }

    /**
     * Edit a routine
     * @param {string} routineId - ID of routine to edit
     */
    editRoutine(routineId) {
        const routine = this.state.recentRoutines.find(r => r.id === routineId);
        if (!routine) {
            this.showCustomAlert('Routine not found', 'error');
            return;
        }

        this.state.editingRoutine = routineId;
        this.state.showEditRoutineModal = true;
        this.render();
    }

    /**
     * Delete a game
     * @param {string} gameId - ID of game to delete
     */
    async deleteGame(gameId) {
        try {
            const game = this.state.recentGames.find(g => g.id === gameId);
            if (!game) {
                throw new Error('Game not found');
            }

            const confirmed = confirm(
                `Are you sure you want to delete this game?\n\n` +
                `Game: ${game.gameName}\n` +
                `Score: ${game.score}\n` +
                `Points: ${game.points || 0}`
            );

            if (!confirmed) {
                return;
            }

            const user = userManager.getCurrentUser();
            const activityDate = game.timestamp || game.endTime || game.date;

            // Remove game from any active friend challenges
            await this.removeSessionFromChallenges(gameId);

            // Only remove points if game wasn't pending
            if (!game.pending) {
                user.totalPoints = Math.max(0, user.totalPoints - (game.points || 0));
                user.totalGames = Math.max(0, (user.totalGames || 0) - 1);
                // Remove makes/putts if game tracked them
                if (game.totalMakes !== undefined) {
                    user.totalMakes = Math.max(0, (user.totalMakes || 0) - (game.totalMakes || 0));
                    user.totalPutts = Math.max(0, (user.totalPutts || 0) - (game.totalAttempts || 0));
                }
                await storageManager.saveUser(user);
                
                // Remove Season XP
                await teamsLeaguesManager.removeSeasonXp(user.id, 'playGame', activityDate);
            }

            // Delete game
            await storageManager.deleteGameCompletion(user.id, gameId);

            // Reload current user to get updated totalPoints
            await userManager.reloadCurrentUser();

            // Reload data
            await this.loadRecentPractice();
            await this.loadLeaderboard();

            // Revalidate achievements if game wasn't pending
            if (!game.pending) {
                const revokedAchievements = await achievementManager.revalidateAchievements(
                    this.state.recentRoutines || [],
                    this.state.recentGames || []
                );
                
                // Remove XP for each revoked achievement
                for (const achievementId of revokedAchievements) {
                    await teamsLeaguesManager.removeSeasonXp(user.id, 'earnAchievement', activityDate);
                }
                
                if (revokedAchievements.length > 0) {
                    this.showCustomAlert(`Game deleted. ${revokedAchievements.length} achievement(s) revoked.`, 'warning');
                } else {
                    this.showCustomAlert('Game deleted successfully', 'success');
                }
            } else {
                this.showCustomAlert('Game deleted successfully', 'success');
            }

            this.render();

        } catch (error) {
            console.error('Error deleting game:', error);
            this.showCustomAlert('Failed to delete game: ' + error.message, 'error');
        }
    }

    /**
     * Edit a game
     * @param {string} gameId - ID of game to edit
     */
    editGame(gameId) {
        const game = this.state.recentGames.find(g => g.id === gameId);
        if (!game) {
            this.showCustomAlert('Game not found', 'error');
            return;
        }

        this.state.editingGame = gameId;
        this.state.showEditGameModal = true;
        this.render();
    }

    /**
     * Change current view
     * @param {string} view - View name
     */
    async changeView(view) {
        this.state.currentView = view;

        // Reload data when switching to practice view
        if (view === 'practice') {
            await userManager.reloadCurrentUser(); // Reload user for fresh totalPoints
            await userManager.loadSessions(); // Reload sessions for fresh data
            await this.loadRecentPractice(); // Reload routines and games
        }

        // Reload data when switching to stats view
        if (view === 'stats') {
            await userManager.reloadCurrentUser(); // Reload user for fresh stats
            await userManager.loadSessions(); // Reload sessions for fresh data
            await this.loadRecentPractice(); // Reload routines and games
        }

        // NOTE: "Game On" achievement is now awarded when completing a game (not viewing tab)
        // This prevents false achievements for users who never complete a game

        this.render();
    }

