    /**
     * Handle game builder form submission
     */
    async handleGameBuilderSubmit(e) {
        e.preventDefault();

        try {
            const formData = {
                name: document.getElementById('gameName').value,
                description: document.getElementById('gameDescription').value,
                difficulty: document.querySelector('input[name="gameLevel"]:checked')?.value || 'Easy',
                duration: document.getElementById('gameDuration').value,
                scoringType: document.querySelector('input[name="scoringType"]:checked')?.value || 'points',
                goal: document.getElementById('gameGoal').value,
                instructions: document.getElementById('gameInstructions').value,
                minPlayers: document.getElementById('minPlayers').value,
                maxPlayers: document.getElementById('maxPlayers').value,
                isPublic: document.getElementById('gameIsPublic').checked
            };

            // Validate
            const errors = gameBuilder.validate(formData);
            if (errors.length > 0) {
                this.showCustomAlert(errors.join('\n'), 'error');
                return;
            }

            // Submit
            const result = await gameBuilder.handleSubmit(formData);

            if (result.success) {
                this.showCustomAlert(result.message, 'success');
                this.state.showGameBuilder = false;
                await this.loadCustomGames();
                this.render();

                // Trigger event
                window.dispatchEvent(new Event('gamesSaved'));
            } else {
                this.showCustomAlert(result.message, 'error');
            }
        } catch (error) {
            console.error('Error saving game:', error);
            this.showCustomAlert('Failed to save game: ' + error.message, 'error');
        }
    }

    /**
     * Open custom game score modal
     */
    openCustomGameScoreModal(game) {
        // Open the bulk log wizard with this game pre-selected
        this.state.showBulkLogWizard = true;
        this.state.bulkLogStep = 1; // Start at player selection
        this.state.bulkLogActivity = 'game'; // Set activity type to game
        this.state.bulkSelectedGame = game; // Pre-select this game
        const currentUser = userManager.getCurrentUser();
        this.state.bulkLogPlayers = currentUser ? [currentUser.id] : [];
        this.state.bulkActivityTab = 'game';
        this.render();

        // Attach event listeners after render
        this.scheduleWizardListeners();
    }

    /**
     * Open routine completion modal for custom/community routine
     */
    async openCustomRoutineCompletionModal(routineId) {
        try {
            let routine = null;
            let activityType = null;

            // Try custom routines first (user's private routines)
            routine = await storageManager.getCustomRoutine(routineId);
            if (routine) {
                activityType = 'custom-routine';
            }

            // Then try community routines (public shared routines)
            if (!routine) {
                routine = this.state.communityRoutines.find(r => r.id === routineId);
                if (routine) {
                    activityType = 'community-routine';
                }
            }

            if (!routine) {
                this.showCustomAlert('Routine not found', 'error');
                return;
            }

            // Open the bulk log wizard with this routine pre-selected
            this.state.showBulkLogWizard = true;
            this.state.bulkLogStep = 1; // Start at player selection
            this.state.bulkLogActivity = activityType; // 'custom-routine' or 'community-routine'
            this.state.bulkSelectedRoutine = routine; // Pre-select this routine
            const currentUser2 = userManager.getCurrentUser();
            this.state.bulkLogPlayers = currentUser2 ? [currentUser2.id] : [];
            this.state.bulkActivityTab = 'routine';
            this.render();

            // Attach event listeners after render
            this.scheduleWizardListeners();
        } catch (error) {
            console.error('Error opening routine modal:', error);
            this.showCustomAlert('Failed to open routine: ' + error.message, 'error');
        }
    }

    /**
     * Rate a community routine
     */
    async rateRoutine(routineId) {
        const rating = prompt('Rate this routine from 1 to 5 stars:', '5');
        if (!rating) return;

        const ratingNum = parseInt(rating);
        if (isNaN(ratingNum) || ratingNum < 1 || ratingNum > 5) {
            this.showCustomAlert('Please enter a number between 1 and 5', 'warning');
            return;
        }

        try {
            const user = userManager.getCurrentUser();
            await storageManager.rateRoutine(user.id, routineId, ratingNum);

            // Reload community routines to show updated rating
            await this.loadCommunityRoutines();

            this.render();
        } catch (error) {
            console.error('Error rating routine:', error);
            this.showCustomAlert('Failed to rate routine: ' + error.message, 'error');
        }
    }

    /**
     * Toggle favorite for a routine
     */
    async toggleFavoriteRoutine(routineId, favorite) {
        try {
            const user = userManager.getCurrentUser();
            await storageManager.toggleFavoriteRoutine(user.id, routineId, favorite);

            // Update state
            if (favorite) {
                this.state.favoriteRoutineIds.push(routineId);
            } else {
                this.state.favoriteRoutineIds = this.state.favoriteRoutineIds.filter(id => id !== routineId);
            }

            // Reload to show updated count
            await this.loadCommunityRoutines();

            this.render();
        } catch (error) {
            console.error('Error toggling favorite:', error);
            this.showCustomAlert('Failed to update favorite: ' + error.message, 'error');
        }
    }

