    /**
     * Main render function
     * Updates the entire UI based on current state
     */
    render() {
        // Prevent concurrent renders
        if (this.isRendering) {
            console.warn('⚠️ Render already in progress, skipping...');
            return;
        }

        this.isRendering = true;
        console.log('🎨 Render started', { showProfileModal: this.state.showProfileModal, currentView: this.state.currentView });

        try {
            const appContainer = document.getElementById('app');
            if (!appContainer) {
                console.error('❌ App container not found');
                return;
            }

            // Show loading state
            if (this.state.loading) {
                appContainer.innerHTML = this.renderLoading();
                return;
            }

            // Show error state
            if (this.state.error) {
                appContainer.innerHTML = this.renderError();
                return;
            }

            // Show login if not authenticated
            if (!authManager.isAuthenticated()) {
                appContainer.innerHTML = this.renderLogin();
                this.attachLoginListeners();
                return;
            }

            // Show main app
            appContainer.innerHTML = this.renderApp();
            this.attachEventListeners();
            this.startChallengeCountdownTimer();

            // Re-insert live banner after DOM rebuild (it lives outside render tree)
            if (this.state.activeLiveSession) {
                this.updateLiveBanner();
            }

            // Re-attach wizard listeners if wizard is open (DOM was just rebuilt)
            if (this.state.showBulkLogWizard || this.state.showBulkLogModal) {
                this.scheduleWizardListeners();
            }
        } catch (error) {
            console.error('❌ Render error:', error);
            this.state.error = error.message;
        } finally {
            this.isRendering = false;
            this.applyMobileNavStyles();
        }
    }

    /**
     * Force mobile bottom nav styles via JS — CSS cascade cannot be
     * reliably won due to multiple stylesheet conflicts in the WebView.
     * Inline JS styles beat all CSS regardless of specificity or order.
     */
    applyMobileNavStyles() {
        const tabs = document.getElementById('main-tabs');
        if (!tabs) return;
        const isMobile = window.innerWidth <= 640;

        if (isMobile) {
            // Move tabs out of main to after #app's last child (bottom of app shell)
            const appEl = document.getElementById('app');
            if (appEl && tabs.parentElement !== appEl) {
                appEl.appendChild(tabs);
            }

            // App shell: fills viewport as flex column
            if (appEl) appEl.style.cssText = 'display:flex;flex-direction:column;height:100dvh;height:100vh;overflow:hidden';

            // Header never scrolls
            const header = document.querySelector('.app-header');
            if (header) header.style.cssText = 'flex-shrink:0';

            // Main scrolls internally
            const main = document.querySelector('.main-content');
            if (main) main.style.cssText = 'flex:1;overflow-y:auto;overflow-x:hidden;min-height:0;-webkit-overflow-scrolling:touch';

            // Style the tab bar
            tabs.style.cssText = [
                'display:flex', 'flex-direction:row', 'flex-wrap:nowrap',
                'align-items:center', 'flex-shrink:0', 'border-radius:0', 'margin:0',
                'padding:0.3rem 0.2rem',
                'padding-bottom:calc(0.3rem + env(safe-area-inset-bottom, 0px))',
                'border-top:2px solid rgba(255,107,53,0.2)',
                'box-shadow:0 -4px 16px rgba(0,0,0,0.18)', 'overflow:hidden'
            ].join(';');

            tabs.querySelectorAll('.tab').forEach(btn => {
                btn.style.cssText = [
                    'flex:1 1 0', 'min-width:0', 'min-height:0', 'height:auto',
                    'padding:0.4rem 0.1rem', 'font-size:0', 'line-height:1',
                    'white-space:nowrap', 'overflow:hidden', 'display:flex',
                    'flex-direction:column', 'align-items:center', 'justify-content:center',
                    'gap:2px', 'border:none', 'cursor:pointer', 'background:transparent'
                ].join(';');
                if (btn.classList.contains('active')) {
                    btn.style.background = 'linear-gradient(135deg,#FF6B35 0%,#D9534F 100%)';
                    btn.style.color = 'white';
                    btn.style.borderRadius = '8px';
                }
                const icon = btn.querySelector('.tab-icon');
                const label = btn.querySelector('.tab-label');
                if (icon) icon.style.cssText = 'font-size:20px;line-height:1;display:block';
                if (label) label.style.cssText = 'font-size:0.62rem;line-height:1;display:block' + (btn.classList.contains('active') ? ';color:white' : '');
            });

        } else {
            // Desktop: move tabs back inside main at the top if they got displaced
            const main = document.querySelector('.main-content');
            if (main && tabs.parentElement !== main) {
                main.insertBefore(tabs, main.firstChild);
            }
            // Clear any mobile inline styles
            tabs.style.cssText = '';
            tabs.querySelectorAll('.tab').forEach(btn => {
                btn.style.cssText = '';
                const icon = btn.querySelector('.tab-icon');
                const label = btn.querySelector('.tab-label');
                if (icon) icon.style.cssText = '';
                if (label) label.style.cssText = '';
            });
            const appEl = document.getElementById('app');
            if (appEl) appEl.style.cssText = '';
            const header = document.querySelector('.app-header');
            if (header) header.style.cssText = '';
            const mainEl = document.querySelector('.main-content');
            if (mainEl) mainEl.style.cssText = '';
        }
    }
