    /**
     * Quit/delete an active challenge (deletes for both users)
     */
    async quitChallenge(challengeId) {
        const challenge = this.state.challenges?.find(c => c.id === challengeId);
        if (!challenge) {
            console.error('Challenge not found:', challengeId);
            return;
        }

        const opponentName = challenge.fromUserId === userManager.getCurrentUser()?.id
            ? challenge.toDisplayName
            : challenge.fromDisplayName;

        const confirmed = confirm(
            `Quit Challenge?\n\nAre you sure you want to quit this challenge? This will delete it for both you and ${opponentName}.`
        );

        if (!confirmed) return;

        try {
            await storageManager.deleteChallenge(challengeId);

            // Remove from local state
            this.state.challenges = (this.state.challenges || []).filter(c => c.id !== challengeId);
            this.state.activeChallenges = (this.state.activeChallenges || []).filter(c => c.id !== challengeId);

            this.showToast({ title: 'Challenge cancelled', type: 'info' });
            this.render();
        } catch (error) {
            console.error('Error quitting challenge:', error);
            this.showToast({ title: 'Failed to quit challenge', type: 'error' });
        }
    }

