                await userManager.reloadCurrentUser();

                // Close tutorial
                this.state.showTutorial = false;
                this.state.tutorialStep = 1;

                // Check for new achievements
                const newAchievements = await achievementManager.checkAchievements(this.state.recentRoutines || [], this.state.recentGames || []);

                // Show success message
                this.showToast({
                    type: 'success',
                    title: '🎉 Tutorial Complete!',
                    message: 'You earned 50 points! Start practicing to unlock more achievements.',
                    duration: 5000
                });

                this.render();

                // Show achievement if unlocked
                if (newAchievements && newAchievements.length > 0) {
                    setTimeout(() => {
                        this.showAchievementSplash(newAchievements[0]);
                    }, 500);
                }
