        if (groupScorerBtn) {
            groupScorerBtn.addEventListener('click', () => this.openBulkLogWizard('session'));
        }

        // Group scorer event delegation
        const gsOverlay = document.getElementById('groupScorerOverlay');
        if (gsOverlay) {
            gsOverlay.addEventListener('click', (e) => {
                const t = e.target;
                const id = t.id || t.closest('[id]')?.id;
                if (id === 'gsClose' || id === 'gsCancel') { this.closeGroupScorer(); return; }
                if (id === 'gsStartScoring')  { this.groupScorerStartScoring(); return; }
                if (id === 'gsMakeBtn' || t.closest('#gsMakeBtn'))  { this.groupScorerMake(); return; }
                if (id === 'gsMissBtn' || t.closest('#gsMissBtn'))  { this.groupScorerMiss(); return; }
                if (id === 'gsUndo')           { this.groupScorerUndo(); return; }
                if (id === 'gsNextPlayer')     { this.groupScorerAdvancePlayer(); this._groupScorerUpdateUI(); return; }
                if (id === 'gsSubmit')         { this.groupScorerSubmit(); return; }
                if (id === 'gsDone')           { this.closeGroupScorer(); return; }
                if (id === 'gsTimerToggle') {
                    if (this.state.groupScorerTimerRunning) this.groupScorerPauseTimer();
                    else this.groupScorerStartTimer();
                    return;
                }
                // Player pill tap
                const pill = t.closest('.gs-pill');
                if (pill) { this.groupScorerSetActivePlayer(pill.dataset.pid); return; }
                // Player row tap in setup
                const row = t.closest('.gs-player-row');
                if (row) {
                    const pid = row.dataset.gsPlayerId;
                    const isSelf = row.dataset.gsIsSelf === 'true';
                    if (isSelf) return; // can't deselect self
                    const already = this.state.groupScorerPlayers.find(p => p.id === pid);
                    if (already) {
                        this.state.groupScorerPlayers = this.state.groupScorerPlayers.filter(p => p.id !== pid);
                    } else {
                        this.state.groupScorerPlayers.push({
                            id: pid,
                            displayName: row.dataset.gsPlayerName || pid,
                            photoURL: row.dataset.gsPlayerPhoto || null
                        });
                    }
                    this.render();
                    return;
                }
            });

            // Distance slider for group scorer
            this.initDistanceSlider('gsSlider', (d) => {
                this.state.groupScorerDistance = d;
            }, this.state.groupScorerDistance || 20);

            // Auto-advance checkbox
            const autoAdv = document.getElementById('gsAutoAdvance');
            if (autoAdv) {
                autoAdv.addEventListener('change', () => {
                    this.state.groupScorerAutoAdvance = autoAdv.checked;
                });
            }

            // Require approval checkbox
            const reqApproval = document.getElementById('gsRequireApproval');
            if (reqApproval) {
                reqApproval.addEventListener('change', () => {
                    this.state.groupScorerRequireApproval = reqApproval.checked;
                });
            }
        }

        // Simple Scorer event delegation (handles all screens)
        const ssOverlay = document.getElementById('simpleScorerOverlay');
        if (ssOverlay) {
            ssOverlay.addEventListener('click', (e) => {
                const target = e.target.closest('[id]');
                if (!target) return;

                if (target.id === 'ssCancel') {
                    this.closeSimpleScorer();
                } else if (target.id === 'ssMakeBtn' || target.closest('#ssMakeBtn')) {
                    this.simpleScorerMake();
                } else if (target.id === 'ssMissBtn' || target.closest('#ssMissBtn')) {
                    this.simpleScorerMiss();
                } else if (target.id === 'ssUndo') {
                    this.simpleScorerUndo();
                } else if (target.id === 'ssTimerToggle') {
                    this.simpleScorerToggleTimer();
                } else if (target.id === 'ssReset') {
                    this.simpleScorerReset();
                } else if (target.id === 'ssScoreDisplay' || target.id === 'ssScoreBig' || target.closest('#ssScoreDisplay')) {
                    // Tap score to edit inline
                    const display = document.getElementById('ssScoreDisplay');
                    const editor = document.getElementById('ssInlineEdit');
                    if (display && editor) {
                        // Populate with current state values
                        const makesInput = document.getElementById('ssEditMakes');
                        const attemptsInput = document.getElementById('ssEditAttempts');
                        if (makesInput) makesInput.value = this.state.simpleScorerMakes;
                        if (attemptsInput) attemptsInput.value = this.state.simpleScorerMakes + this.state.simpleScorerMisses;
                        display.style.display = 'none';
                        editor.style.display = 'block';
                        if (makesInput) makesInput.focus();
                    }
                } else if (target.id === 'ssEditCancel') {
                    const display = document.getElementById('ssScoreDisplay');
                    const editor = document.getElementById('ssInlineEdit');
                    if (display && editor) {
                        editor.style.display = 'none';
                        display.style.display = '';
                    }
                } else if (target.id === 'ssEditApply') {
                    const makesVal = parseInt(document.getElementById('ssEditMakes')?.value) || 0;
                    const attemptsVal = parseInt(document.getElementById('ssEditAttempts')?.value) || 0;
                    if (attemptsVal > 0 && makesVal <= attemptsVal) {
                        this.state.simpleScorerMakes = makesVal;
                        this.state.simpleScorerMisses = attemptsVal - makesVal;
                        this.state.simpleScorerHistory = [];
                        // Build history from manual values
                        for (let i = 0; i < makesVal; i++) this.state.simpleScorerHistory.push({ type: 'make' });
                        for (let i = 0; i < attemptsVal - makesVal; i++) this.state.simpleScorerHistory.push({ type: 'miss' });
                        // Lock slider since we now have data
                        const sliderContainer = document.getElementById('ssSliderContainer');
                        if (sliderContainer) sliderContainer.classList.add('dist-slider-locked');
                        // Close editor, update DOM
                        const display = document.getElementById('ssScoreDisplay');
                        const editor = document.getElementById('ssInlineEdit');
                        if (display && editor) {
                            editor.style.display = 'none';
                            display.style.display = '';
                        }
                        this.simpleScorerAutoStartTimer();
                        this.simpleScorerUpdateDOM();
                    } else {
                        this.showToast({ type: 'error', title: 'Makes must be ≤ attempts' });
                    }
                } else if (target.id === 'ssSubmit') {
                    this.simpleScorerSubmit();
                } else if (target.id === 'ssNewSession') {
                    this.simpleScorerNewSession();
                } else if (target.id === 'ssDone') {
                    this.closeSimpleScorer();
                }
            });

            // Initialize distance slider for Simple Scorer
            this.initDistanceSlider('ssSlider', (dist) => {
                this.state.simpleScorerDistance = dist;
            }, this.state.simpleScorerDistance || 20);
        }

