        const friends = this.state.friends || [];
        const pendingRequests = this.state.pendingFriendRequests || [];
        const sentRequests = this.state.sentFriendRequests || [];
        const searchResults = this.state.friendSearchResults || [];
        const leaderboardPlayers = this.state.leaderboard || [];

        // Get current user and existing friend IDs to filter suggestions
        const currentUser = userManager.getCurrentUser();
        const friendIds = friends.map(f => f.id);
        const pendingIds = pendingRequests.map(r => r.fromUserId || r.id);
        const sentIds = sentRequests.map(r => r.toUserId);

        // Suggest players from leaderboard who aren't already friends or pending (either direction)
        const suggestedPlayers = leaderboardPlayers
            .filter(p => p.id !== currentUser?.id && !friendIds.includes(p.id) && !pendingIds.includes(p.id))
