        if (tournamentBracketToggle) {
            tournamentBracketToggle.addEventListener('click', () => {
                const t = this.state.tournamentState;
                const isLarge = (t?.participants?.length || 0) >= 16;
                const current = this.state.tournamentBracketExpanded ?? !isLarge;
                this.state.tournamentBracketExpanded = !current;
                this.updateBulkLogWizardUI();
            });
        }

        // Putt 100 - Reset button
        const putt100ResetBtn = document.getElementById('bulkLogResetGamePutt100');
