    /**
     * LADDER CHALLENGE HANDLERS
     */

    /**
     * Ladder - Handle score (0-3)
     */
    handleLadderScore(score) {
        if (this.isProcessingGameAction) {
            console.warn('⚠️ Already processing an action, please wait...');
            return;
        }

        this.isProcessingGameAction = true;

        try {
            const gameState = this.state.ladderState;
            const currentPlayer = gameState.playerProgress[gameState.currentPlayerIdx];
            const distances = [10, 15, 20, 25, 30, 35, 40, 45, 50, 55];

            // Record the score
            currentPlayer.scores[currentPlayer.currentLevel] = score;

            if (score === 0) {
                // Game over for this player
                currentPlayer.isComplete = true;
                currentPlayer.maxDistance = distances[currentPlayer.currentLevel];
            } else {
                // Advance to next level
                currentPlayer.maxDistance = distances[currentPlayer.currentLevel];
                currentPlayer.currentLevel++;

                // Check if completed all 10 levels
                if (currentPlayer.currentLevel >= 10) {
                    currentPlayer.isComplete = true;
                    currentPlayer.maxDistance = 55;
                }
            }

            this.updateBulkLogWizardUI();
            this.isProcessingGameAction = false;
        } catch (error) {
            console.error('Error in handleLadderScore:', error);
            this.isProcessingGameAction = false;
        }
    }

    /**
     * Ladder - Move to next player
     */
    handleLadderNextPlayer() {
        if (this.isProcessingGameAction) {
            console.warn('⚠️ Already processing an action, please wait...');
            return;
        }

        this.isProcessingGameAction = true;

        try {
            const gameState = this.state.ladderState;

            if (!gameState || !gameState.playerProgress) {
                console.error('❌ Invalid game state');
                this.isProcessingGameAction = false;
                return;
            }

            const totalPlayers = gameState.playerProgress.length;
            let attempts = 0;

            // Find next player who isn't complete
            do {
                gameState.currentPlayerIdx = (gameState.currentPlayerIdx + 1) % totalPlayers;
                attempts++;
            } while (gameState.playerProgress[gameState.currentPlayerIdx].isComplete && attempts < totalPlayers);


            this.updateBulkLogWizardUI();
            this.isProcessingGameAction = false;
        } catch (error) {
            console.error('Error in handleLadderNextPlayer:', error);
            this.isProcessingGameAction = false;
        }
    }

