    /**
     * PAR GAME HANDLERS
     */

    /**
     * Par Game - Handle score (1-15)
     */
    handleParScore(score) {
        if (this.isProcessingGameAction) {
            console.warn('⚠️ Already processing an action, please wait...');
            return;
        }

        this.isProcessingGameAction = true;

        try {
            const gameState = this.state.parGameState;
            const currentPlayer = gameState.playerProgress[gameState.currentPlayerIdx];

            // Record the score for current hole
            currentPlayer.scores[gameState.currentHole] = score;

            // Update total score
            currentPlayer.totalScore = currentPlayer.scores.reduce((sum, s) => sum + (s || 0), 0);


            // Move to next player
            let nextPlayerIdx = (gameState.currentPlayerIdx + 1) % gameState.playerProgress.length;

            // Skip players who already completed this hole
            let attempts = 0;
            while (gameState.playerProgress[nextPlayerIdx].scores[gameState.currentHole] !== null && attempts < gameState.playerProgress.length) {
                nextPlayerIdx = (nextPlayerIdx + 1) % gameState.playerProgress.length;
                attempts++;
            }

            gameState.currentPlayerIdx = nextPlayerIdx;

            this.updateBulkLogWizardUI();
            this.isProcessingGameAction = false;
        } catch (error) {
            console.error('Error in handleParScore:', error);
            this.isProcessingGameAction = false;
        }
    }

    /**
     * Par Game - Move to next hole
     */
    handleParNextHole() {
        if (this.isProcessingGameAction) {
            console.warn('⚠️ Already processing an action, please wait...');
            return;
        }

        this.isProcessingGameAction = true;

        try {
            const gameState = this.state.parGameState;

            // Move to next hole
            gameState.currentHole++;

            // Reset to first player
            gameState.currentPlayerIdx = 0;

            // Check if game is complete (all 9 holes done)
            if (gameState.currentHole >= 9) {
                gameState.playerProgress.forEach(p => p.isComplete = true);
            }

            this.updateBulkLogWizardUI();
            this.isProcessingGameAction = false;
        } catch (error) {
            console.error('Error in handleParNextHole:', error);
            this.isProcessingGameAction = false;
        }
    }

    /**
     * Par Game - Reset game
     */
    handleParReset() {
        if (confirm('Reset the game? All progress will be lost.')) {
            this.state.parGameState = null;
            this.updateBulkLogWizardUI();
        }
    }

    /**
     * Par Game - Submit results
     */
    async handleParSubmit() {
        // Prevent double-submission
        if (this.state.isSavingGame) {
            return;
        }

        try {
            this.state.isSavingGame = true;
            showSpinner('Saving game results...');

            const gameState = this.state.parGameState;
            const gameId = 'par_game';
            const game = PUTTING_GAMES.find(g => g.id === gameId);

            const now = new Date();
            const date = getLocalDateString(now);

            // Find the winner (lowest score)
            const minScore = Math.min(...gameState.playerProgress.map(p => p.totalScore));
            const winner = gameState.playerProgress.find(p => p.totalScore === minScore);

            // Save completion for each player
            const currentUserId = userManager.getCurrentUser()?.id;

            for (const player of gameState.playerProgress) {
                // Calculate points - Par is strokes type
                const scoreData = {
                    score: player.totalScore,
                    par: 18, // 9 holes x 2 par
                    playerCount: gameState.playerProgress.length
                };

                const points = calculateGamePoints(
                    { scoring: { type: 'strokes' } },
                    scoreData
                );

                const gameCompletion = {
                    userId: player.playerId,
                    gameId: gameId,
                    gameName: game.name,
                    scoringType: 'strokes',
                    date: date,
                    timestamp: now.toISOString(),
                    endTime: now.toISOString(),
                    timeInMinutes: this._bulkScoringStartTime ? Math.max(1, Math.ceil((Date.now() - this._bulkScoringStartTime) / 60000)) : null,
                    score: player.totalScore,
                    points: points,
                    playerCount: gameState.playerProgress.length,
                    metadata: {
                        totalScore: player.totalScore,
                        scores: player.scores,
                        birdies: player.scores.filter(s => s === 1).length,
                        pars: player.scores.filter(s => s === 2).length,
                        bogeys: player.scores.filter(s => s === 3).length,
                        isWinner: player.playerId === winner.playerId
                    }
                };


                // If logging for self, save directly; otherwise save as pending (if friends)
                if (player.playerId === currentUserId) {
                    const gameCompletionId = await storageManager.addGameScore(gameCompletion);
                    
                    // Update challenges
                    await userManager.reloadCurrentUser();
                    await this.updateChallengesAfterActivity({
                        id: gameCompletionId, // Use actual game completion ID
                        date: gameCompletion.date,
                        points: gameCompletion.points,
                        makes: gameCompletion.score || 0,
                        attempts: gameCompletion.score || 0
                    }, 'game');
                } else {
                    // Check if friends first
                    const isFriend = await storageManager.areFriends(currentUserId, player.playerId);
                    
                    if (isFriend) {
                        const completionId = `${gameId}_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

                        // Save to YOUR account
                        const yourRecord = {
                            id: completionId,
                            userId: currentUserId,
                            forUserId: player.playerId,
                            forUserName: player.playerName,
                            ...gameCompletion,
                            loggedBy: currentUserId,
                            loggedByName: userManager.getCurrentUser().displayName,
                            excludeFromStats: true
                        };

                        await storageManager.set(`users/${currentUserId}/gameCompletions`, completionId, yourRecord);

                        // Try to save to THEIR account as pending
                        try {
                            const theirGame = {
                                id: completionId,
                                userId: player.playerId,
                                ...gameCompletion,
                                loggedBy: currentUserId,
                                loggedByName: userManager.getCurrentUser().displayName,
                                pending: true,
                                excludeFromStats: true
                            };

                            await storageManager.set(`users/${player.playerId}/gameCompletions`, completionId, theirGame);
                        } catch (error) {
                            console.error(`❌ Failed to save to ${player.playerName}'s account:`, error);
                        }
                    } else {
                        console.warn(`Skipping save for ${player.playerName} - not friends`);
                    }
                }
            }

            // Reload user to get updated points
            await userManager.reloadCurrentUser();

            await this.loadRecentPractice();
            await this.loadLeaderboard();

            // Reset game state
            this.state.parGameState = null;
            this.state.isSavingGame = false;

            removeSpinner();
            this.closeBulkLogWizard();
            this.render();
            this.showCustomAlert(`🏆 ${winner.playerName} wins with ${minScore} strokes!`, 'success');

        } catch (error) {
            console.error('Error submitting Par Game:', error);
            removeSpinner();
            this.state.isSavingGame = false;
            this.render();
            this.showCustomAlert('Error saving game results. Please try again.', 'error');
        }
    }

