    /**
     * POINTS POKER HANDLERS
     */

    /**
     * Points Poker - Start Timer
     */
    handlePokerStartTimer() {
        this.state.pointsPokerState.timerStarted = true;
        this.state.pointsPokerState.startTime = Date.now();

        // Set up timer to update display every second
        this.pokerTimerInterval = setInterval(() => {
            if (!this.state.pointsPokerState || !this.state.pointsPokerState.timerStarted) {
                clearInterval(this.pokerTimerInterval);
                this.pokerTimerInterval = null;
                return;
            }

            // Calculate time remaining
            const elapsed = Math.floor((Date.now() - this.state.pointsPokerState.startTime) / 1000);
            const totalSeconds = this.state.pointsPokerState.timeLimit * 60;
            const timeRemaining = Math.max(0, totalSeconds - elapsed);

            // Update timer display directly in DOM
            const timerElement = document.querySelector('.poker-timer h3');
            if (timerElement) {
                const mins = Math.floor(timeRemaining / 60);
                const secs = timeRemaining % 60;
                timerElement.textContent = `${mins}:${secs.toString().padStart(2, '0')}`;

                // Update warning class
                const timerContainer = document.querySelector('.poker-timer');
                if (timerContainer) {
                    if (timeRemaining <= 60) {
                        timerContainer.classList.add('timer-warning');
                    } else {
                        timerContainer.classList.remove('timer-warning');
                    }
                }
            }

            // If time runs out, complete current player and re-render
            if (timeRemaining === 0) {
                const currentPlayer = this.state.pointsPokerState.playerProgress[this.state.pointsPokerState.currentPlayerIdx];
                if (!currentPlayer.isComplete) {
                    currentPlayer.isComplete = true;
                    clearInterval(this.pokerTimerInterval);
                    this.pokerTimerInterval = null;
                    this.updateBulkLogWizardUI();
                }
            }
        }, 1000);

        this.updateBulkLogWizardUI();
    }

    /**
     * Points Poker - Handle Shot
     */
    handlePokerShot(distance) {
        if (this.isProcessingGameAction) {
            console.warn('⚠️ Already processing an action, please wait...');
            return;
        }

        this.isProcessingGameAction = true;

        try {
            const gameState = this.state.pointsPokerState;
            const currentPlayer = gameState.playerProgress[gameState.currentPlayerIdx];

            // Calculate base points
            const pointsMap = {
                'inside': 1,
                '20': 2,
                '30': 3,
                '40': 5
            };

            let basePoints = pointsMap[distance];
            let actualPoints = basePoints;
            let isStreak = false;

            // Check for streak bonus (3 in a row from same distance)
            if (currentPlayer.lastThree.length === 3 &&
                currentPlayer.lastThree[0].distance === distance &&
                currentPlayer.lastThree[1].distance === distance &&
                currentPlayer.lastThree[2].distance === distance) {
                // 2x multiplier for streak!
                actualPoints = basePoints * 2;
                isStreak = true;
                currentPlayer.streaks++;
            }

            // Add shot to history
            const shot = {
                distance: distance,
                basePoints: basePoints,
                actualPoints: actualPoints,
                bonus: isStreak
            };

            currentPlayer.shots.push(shot);
            currentPlayer.score += actualPoints;

            // Update last three
            currentPlayer.lastThree.push(shot);
            if (currentPlayer.lastThree.length > 3) {
                currentPlayer.lastThree.shift();
            }


            this.updateBulkLogWizardUI();
            this.isProcessingGameAction = false;
        } catch (error) {
            console.error('Error in handlePokerShot:', error);
            this.isProcessingGameAction = false;
        }
    }

